const string Source = "MyApp.Agents";
using var tracer = Sdk.CreateTracerProviderBuilder()
    .AddSource(Source)
    .AddAzureMonitorTraceExporter(o => o.ConnectionString = appInsights)
    .Build();

AIAgent agent = new ChatClientAgent(chatClient, name: "Demo")
    .AsBuilder()
    .UseOpenTelemetry(sourceName: Source, cfg => cfg.EnableSensitiveData = false)
    .Build();                       // agent layer only: no duplicate prompts

AIAgent harness = chatClient.AsHarnessAgent(
    new HarnessAgentOptions { OpenTelemetrySourceName = Source });

var local = new LocalEvaluator(
    EvalChecks.KeywordCheck("weather"),
    EvalChecks.ToolCalledCheck("get_weather"));
var foundry = new FoundryEvals(chatConfiguration, FoundryEvals.Relevance);

AgentEvaluationResults r = await agent.EvaluateAsync(
    new[] { "Weather in Seattle?", "Plan a trip to Portland" },
    foundry, numRepetitions: 3);
r.AssertAllPassed();
